@php($editing=isset($classroom))<x-layouts.app :title="$editing?'Edit Rombel':'Tambah Rombel'" :breadcrumbs="['Beranda','Kesiswaan','Kelas & Rombel',$editing?'Edit':'Tambah']"><form method="post" action="{{ $editing?route('classrooms.update',$classroom):route('classrooms.store') }}" class="space-y-5">@csrf @if($editing)@method('PUT')@endif<x-ui.page-header :title="$editing?'Edit Rombongan Belajar':'Tambah Rombongan Belajar'" description="Isi data rombel untuk satu tahun ajaran."/><x-ui.card><div class="grid gap-4 md:grid-cols-2"><label><span class="label">Tahun Ajaran</span><select class="input" name="academic_year_id" required>@foreach($years as $y)<option value="{{ $y->id }}" @selected(old('academic_year_id',$classroom->academic_year_id??$years->firstWhere('is_active',true)?->id)==$y->id)>{{ $y->name }}</option>@endforeach</select></label><label><span class="label">Tingkat Kelas</span><select class="input" id="grade" name="grade_level_id" required>@foreach($grades as $g)<option value="{{ $g->id }}" data-name="{{ $g->name }}" @selected(old('grade_level_id',$classroom->grade_level_id??'')==$g->id)>{{ $g->name }}</option>@endforeach</select><small>Pilih tingkat utama siswa, misalnya Kelas 2.</small></label><label><span class="label">Program Kelas <x-ui.help-tip title="Program Kelas" content="Pilih Reguler atau Full Day sesuai layanan yang berlaku untuk rombel."/></span><select class="input" name="program_type" required><option value="regular" @selected(old('program_type',$classroom->program_type?->value??'regular')==='regular')>Reguler</option><option value="full_day" @selected(old('program_type',$classroom->program_type?->value??'regular')==='full_day')>Full Day</option></select></label><label><span class="label">Kode Rombel <x-ui.help-tip title="Kode rombel" content="Kode singkat untuk membedakan rombel pada tingkat yang sama. Contoh: II A, II B, atau 2A."/></span><input class="input" id="code" name="code" maxlength="50" required value="{{ old('code',$classroom->code??'') }}" placeholder="II A">@error('code')<p class="text-sm text-red-600">{{ $message }}</p>@enderror</label><label><span class="label">Nama Rombel <x-ui.help-tip title="Nama rombel" content="Nama tambahan, misalnya AL-MU'MIN. Boleh dikosongkan."/></span><input class="input" id="name" name="name" value="{{ old('name',$classroom->name??'') }}" placeholder="AL-MU'MIN"></label><label><span class="label">Kapasitas <x-ui.help-tip title="Kapasitas" content="Kapasitas digunakan sebagai pengingat; kelebihan siswa akan diberi peringatan."/></span><input class="input" name="capacity" type="number" min="1" max="100" value="{{ old('capacity',$classroom->capacity??config('classrooms.default_capacity')) }}"></label><label><span class="label">Ruang Kelas</span><input class="input" name="room_name" value="{{ old('room_name',$classroom->room_name??'') }}"></label>@can('classrooms.assign-homeroom')<label><span class="label">Wali Kelas <x-ui.help-tip title="Wali kelas" content="Hanya personalia aktif dengan jabatan Guru atau Kepala Madrasah yang dapat dipilih."/></span><select class="input" name="homeroom_personnel_id"><option value="">Belum ditentukan</option>@foreach($personnel as $p)<option value="{{ $p->id }}" @selected(old('homeroom_personnel_id',$classroom->homeroom_personnel_id??'')==$p->id)>{{ $p->full_name }} — {{ $p->position }}</option>@endforeach</select></label>@endcan<label><span class="label">Status</span><select class="input" name="is_active"><option value="1">Aktif</option><option value="0" @selected(old('is_active',$classroom->is_active??true)==false)>Nonaktif</option></select></label><label class="md:col-span-2"><span class="label">Catatan</span><textarea class="input" name="notes">{{ old('notes',$classroom->notes??'') }}</textarea></label></div><div class="mt-5 rounded-xl bg-emerald-50 p-4"><p class="text-sm">Nama yang akan tampil:</p><strong id="preview">—</strong></div></x-ui.card><div class="flex justify-end gap-2"><a class="btn btn-secondary" href="{{ route('classrooms.index') }}">Batal</a><button class="btn btn-primary">Simpan Rombel</button></div></form><script>const preview=()=>{let g=document.querySelector('#grade option:checked')?.dataset.name||'Kelas',c=document.querySelector('#code').value.trim(),n=document.querySelector('#name').value.trim();document.querySelector('#preview').textContent=g+' - '+(c||'Kode Rombel')+(n?' ('+n+')':'')};document.querySelectorAll('#grade,#code,#name').forEach(x=>x.addEventListener('input',preview));preview()</script></x-layouts.app>
